/** Native phone wizard. No WebView bridge, remote scripts, arbitrary commands or automatic grants. */
public final class SetupActivity extends Activity {
    static final int INK=0xff172838,MUTED=0xff536575,BLUE=0xff244fd2,PAPER=0xfff5f7f9;
    final Handler ui=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();final ScheduledExecutorService deadlines=Executors.newSingleThreadScheduledExecutor();
    LinearLayout page;volatile TvConnection connection;PhoneInstaller installer;VerifiedBundle bundle;boolean busy,gate,disconnected;int screen;String model="",address="",connectPort="",pairPort="",style="clean",position="bottom",size="medium",spacing="comfortable";List<String> apps=new ArrayList<>(),chosen=new ArrayList<>();JSONObject reviewed;Runnable approved;long gateStarted;
    int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    TextView text(String value,int sp,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(sp);t.setTextColor(color);t.setTypeface(getResources().getFont(R.font.outfit));t.setPadding(0,dp(4),0,dp(12));return t;}
    void page(int step,String title,String intro){screen=step;page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(24),dp(24),dp(24),dp(32));page.setBackgroundColor(PAPER);page.addView(text("DV Freedom Setup",18,BLUE));page.addView(text(new String[]{"Welcome","1 of 4 · Connect","2 of 4 · Your Home","3 of 4 · Review","4 of 4 · Check your TV"}[Math.max(0,Math.min(4,step))],14,MUTED));page.addView(text(title,30,INK));page.addView(text(intro,17,MUTED));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(page);setContentView(scroll);}
    Button button(String label,boolean primary,Runnable action){Button b=new Button(this);b.setAllCaps(false);b.setText(label);b.setTextColor(primary?Color.WHITE:INK);b.setTextSize(17);b.setMinHeight(dp(52));GradientDrawable bg=new GradientDrawable();bg.setColor(primary?BLUE:Color.WHITE);bg.setCornerRadius(dp(10));if(!primary)bg.setStroke(dp(1),0xffcbd5de);b.setBackground(bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);p.bottomMargin=dp(4);page.addView(b,p);b.setOnClickListener(v->{if(!busy)action.run();});return b;}
    EditText field(String label,String value,boolean number,boolean secret){page.addView(text(label,15,INK));EditText e=new EditText(this);e.setText(value);e.setTextColor(INK);e.setSingleLine(true);e.setInputType(number?InputType.TYPE_CLASS_NUMBER|(secret?InputType.TYPE_NUMBER_VARIATION_PASSWORD:0):InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);e.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);e.setMinHeight(dp(52));page.addView(e);return e;}
    Spinner choice(String label,String[] values,String current){page.addView(text(label,15,INK));Spinner s=new Spinner(this);s.setMinimumHeight(dp(52));s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));s.setSelection(Math.max(0,Arrays.asList(values).indexOf(current)));page.addView(s);return s;}
    void error(String message,Runnable back){page(0,"Let’s check that.",message);button("Back",true,back);button("Support report",false,this::support);}
    interface Job<T>{T run()throws Exception;}
    <T> void work(String title,Job<T> job,java.util.function.Consumer<T> done,Runnable back){if(busy)return;busy=true;page(screen,title,"Keep the phone connected. This step does only the operation you selected.");ProgressBar progress=new ProgressBar(this);page.addView(progress);TvConnection target=connection;ScheduledFuture<?> timeout=deadlines.schedule(()->{if(target!=null)target.close();},120,TimeUnit.SECONDS);worker.execute(()->{try{T result=job.run();ui.post(()->{busy=false;if(!isDestroyed())done.accept(result);});}catch(Exception bad){String message=bad instanceof java.io.IOException||bad instanceof IllegalArgumentException||bad instanceof IllegalStateException?bad.getMessage():"This step could not finish. Check the TV and use the saved-operation check before retrying.";ui.post(()->{busy=false;if(!isDestroyed())error(message==null?"Connection unavailable. Check the TV and connection port.":message,back);});}finally{timeout.cancel(false);}});}
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);welcome();}
    void welcome(){if(connection!=null)connection.close();connection=null;installer=null;reviewed=null;page(0,"A calmer Home. From your phone.","Install and preview DV Freedom on an Android TV using its Wireless debugging pairing code. Your TV Home stays available; every installation is reviewed.");page.addView(text("You need Android 10+ on this phone, a secure phone lock, and a TV with pairing-code Wireless debugging on the same trusted network. Pairing and connection ports are different.",16,INK));page.addView(text("TV has only USB/legacy ADB? Use desktop Setup. LG webOS and Samsung Tizen also use their separate desktop paths; this app cannot install Android APKs on them.",16,MUTED));button("Connect my Android TV",true,this::connect);button("Check saved setup",false,this::connect);button("Privacy & licences",false,this::about);}
    void connect(){page(1,"Connect the TV you choose.","On the TV: Settings → System → Developer options → Wireless debugging. Open Pair device with pairing code. Leave that dialog open and copy both ports carefully. No scanning or connection happens until you press a button.");EditText host=field("TV IPv4 address",address,false,false),port=field("Connection port — main Wireless debugging screen",connectPort,true,false),pair=field("Pairing port — pairing-code dialog",pairPort,true,false),code=field("Six-digit pairing code", "",true,true);CheckBox consent=new CheckBox(this);consent.setText("This is my TV and I authorize this phone’s debugging connection.");consent.setTextColor(INK);consent.setMinHeight(dp(48));page.addView(consent);
        button("Pair & connect",true,()->{if(!consent.isChecked()){Toast.makeText(this,"Review the connection choice first",Toast.LENGTH_LONG).show();return;}try{address=SetupPolicy.host(host.getText().toString().trim());connectPort=port.getText().toString().trim();pairPort=pair.getText().toString().trim();int cp=SetupPolicy.port(connectPort),pp=SetupPolicy.port(pairPort);String digits=code.getText().toString();if(!digits.matches("[0-9]{6}"))throw new IllegalArgumentException("Use the current six-digit TV code");code.setText("");open(address,cp,pp,digits);}catch(Exception bad){Toast.makeText(this,bad.getMessage(),Toast.LENGTH_LONG).show();}});
        button("Reconnect a previously paired TV",false,()->{if(!consent.isChecked()){Toast.makeText(this,"Review the connection choice first",Toast.LENGTH_LONG).show();return;}try{address=SetupPolicy.host(host.getText().toString().trim());connectPort=port.getText().toString().trim();open(address,SetupPolicy.port(connectPort),0,"");}catch(Exception bad){Toast.makeText(this,bad.getMessage(),Toast.LENGTH_LONG).show();}});button("Back",false,this::welcome);
    }
    void open(String host,int port,int pairingPort,String code){if(connection!=null)connection.close();connection=null;work("Connecting to your chosen TV",()->{TvConnection c=new TvConnection(this,host,port);connection=c;if(pairingPort!=0)c.pair(pairingPort,code);c.connect();model=c.model();if(c.api()<26)throw new IllegalArgumentException("This TV needs Android 8 or newer");apps=c.apps();bundle=new VerifiedBundle(this);String id=SetupPolicy.sha(host.getBytes(java.nio.charset.StandardCharsets.UTF_8));installer=new PhoneInstaller(new AndroidDevice(this,c),bundle.release,bundle.apk,new File(getFilesDir(),"recovery/"+id));return true;},ok->confirmTV(),this::connect);}
    void confirmTV(){page(1,"Is this your TV?",model+"\nConnected using paired TLS. Check the TV you just paired, then confirm this identity before any write.");page.addView(text("ADB peer fingerprint\n"+connection.candidate,14,MUTED));CheckBox confirm=new CheckBox(this);confirm.setText("This is the TV I paired and intend to set up.");confirm.setTextColor(INK);page.addView(confirm);button("Confirm TV and continue",true,()->{if(!confirm.isChecked())return;connection.confirmPeer();homeChoices();});button("Cancel and disconnect",false,()->{connection.close();welcome();});}
    String name(String pkg){String[][] names={{"com.netflix.ninja","Netflix"},{"com.google.android.youtube.tv","YouTube"},{"com.amazon.amazonvideo.livingroom","Prime Video"},{"com.crunchyroll.crunchyroid","Crunchyroll"},{"com.mvas.stb.emu.pro","STB Emu Pro"},{"com.mvas.stb.emu.free","STB Emu"},{"com.apple.atve.androidtv.appletv","Apple TV"},{"com.disney.disneyplus","Disney+"}};for(String[] n:names)if(n[0].equals(pkg))return n[1];return pkg;}
    void homeChoices(){page(2,"Make a new Home to try.","Choose one to eight apps. The timed preview creates a separate profile; your current profile, app order and wallpaper stay saved. Existing media is not copied.");Spinner st=choice("Home style",new String[]{"classic","clean","glass","cinema"},style),pos=choice("App position",new String[]{"top","middle","bottom"},position),sz=choice("Icon size",new String[]{"small","medium","large"},size),gap=choice("App spacing",new String[]{"compact","comfortable","wide"},spacing);
        button("Choose apps · "+chosen.size()+" / 8",false,()->{remember(st,pos,sz,gap);String[] labels=apps.stream().map(this::name).toArray(String[]::new);boolean[] checked=new boolean[apps.size()];for(int n=0;n<apps.size();n++)checked[n]=chosen.contains(apps.get(n));List<String> draft=new ArrayList<>(chosen);AlertDialog a=new AlertDialog.Builder(this).setTitle("Apps in your new Home").setMultiChoiceItems(labels,checked,(d,n,on)->{String p=apps.get(n);if(on){if(draft.size()>=8){((AlertDialog)d).getListView().setItemChecked(n,false);Toast.makeText(this,"Choose up to eight apps",Toast.LENGTH_SHORT).show();}else draft.add(p);}else draft.remove(p);}).setPositiveButton("Use these apps",(d,n)->{chosen=draft;homeChoices();}).setNegativeButton("Cancel",null).create();a.show();});
        for(int i=0;i<chosen.size();i++){final int n=i;page.addView(text((i+1)+". "+name(chosen.get(i)),17,INK));if(i>0)button("Move "+name(chosen.get(i))+" earlier",false,()->{remember(st,pos,sz,gap);Collections.swap(chosen,n,n-1);homeChoices();});}
        button("Review installation",true,()->{remember(st,pos,sz,gap);try{JSONObject choices=SetupPolicy.choices(style,position,size,spacing,chosen);work("Preparing your private recovery point",()->installer.review(choices),r->{reviewed=r;review();},this::homeChoices);}catch(Exception bad){Toast.makeText(this,bad.getMessage(),Toast.LENGTH_LONG).show();}});button("Check a saved operation",false,this::check);button("Disconnect",false,()->{connection.close();welcome();});
    }
    void remember(Spinner a,Spinner b,Spinner c,Spinner d){style=a.getSelectedItem().toString();position=b.getSelectedItem().toString();size=c.getSelectedItem().toString();spacing=d.getSelectedItem().toString();}
    void review(){page(3,"Review before installing.",bundle.release.optString("versionName")+"\n"+model+"\n"+style+" · "+position+" · "+size+" · "+spacing);page.addView(text("Signed offline APK verified. Signer and downgrade checks are required. Home stays selected; no permissions, debloating, boot services or network providers are enabled.",16,INK));page.addView(text("Recovery saves launcher settings/app order/media references and an existing APK on this phone. It is not a full backup of streaming accounts, private app data, all profiles or media files. No automatic APK downgrade.",16,MUTED));for(String p:chosen)page.addView(text(name(p),16,INK));CheckBox consent=new CheckBox(this);consent.setText("Install this reviewed launcher and open its temporary 45-second preview on this TV.");consent.setTextColor(INK);page.addView(consent);Button install=button("Approve with phone lock",true,()->{if(!consent.isChecked())return;String hash=reviewed.optString("planHash");authorize(()->work("Installing and verifying your launcher",()->installer.install(hash),this::result,this::check));});install.setEnabled(false);consent.setOnCheckedChangeListener((b,on)->install.setEnabled(on));button("Back without installing",false,this::homeChoices);}
    void authorize(Runnable action){KeyguardManager manager=getSystemService(KeyguardManager.class);if(manager==null||!manager.isDeviceSecure()){error("Set a secure screen lock on this phone to approve TV writes, or use desktop Setup. The app cannot create or bypass a phone lock.",this::homeChoices);return;}Intent intent=manager.createConfirmDeviceCredentialIntent("Approve DV Freedom Setup","Approve only the reviewed operation on your paired TV.");if(intent==null){error("Phone confirmation is unavailable. Use desktop Setup.",this::homeChoices);return;}approved=action;gate=true;gateStarted=SystemClock.elapsedRealtime();startActivityForResult(intent,401);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=401)return;gate=false;Runnable action=approved;approved=null;if(result==RESULT_OK&&SystemClock.elapsedRealtime()-gateStarted<300000&&action!=null)action.run();else if(reviewed!=null)review();else homeChoices();}
    void check(){if(installer==null){connect();return;}work("Checking the saved operation",()->installer.check(),this::result,this::homeChoices);}
    void result(JSONObject r){String status=r.optString("state");page(4,status.equals("awaiting-tv")?"Look at your TV.":status.equals("kept")?"Your new profile is kept.":status.equals("reverted")?"The preview reverted.":status.equals("checked")?"No new installation confirmed.":status.equals("restored")?"Saved settings restored.":"The APK is installed.",status.equals("awaiting-tv")?"Use the real remote to choose Keep or Revert within 45 seconds. Timeout restores the previous profile. Keep does not change the default Home.":"Your original TV Home stays available. App launch and APK verification do not prove streaming playback.");button("Check TV result",true,this::check);if(status.equals("installed-no-preview"))button("Open reviewed timed preview",false,()->authorize(()->work("Opening the timed preview",()->installer.resumePreview(),this::result,this::check)));if(!r.isNull("backup")&&!status.equals("awaiting-tv"))button("Review restoring saved profile",false,()->work("Reviewing the saved profile",()->installer.reviewRestore(r.optString("id")),draft->{page(4,"Restore the saved profile?","Replaces launcher preferences with profile "+draft.optString("profile")+". Media files and streaming accounts are not restored. APK code is not downgraded. A changed TV revision will cancel this operation.");CheckBox consent=new CheckBox(this);consent.setText("Restore this reviewed launcher backup only.");consent.setTextColor(INK);page.addView(consent);Button apply=button("Approve restore with phone lock",true,()->authorize(()->work("Restoring saved launcher settings",()->installer.restore(draft.optString("id"),draft.optString("revision")),this::result,this::check)));apply.setEnabled(false);consent.setOnCheckedChangeListener((v,on)->apply.setEnabled(on));button("Cancel",false,this::check);},this::check));button("Review another Home draft",false,this::homeChoices);button("Support report",false,this::support);page.addView(text("On TV, verify Home, arrows/OK, Back, Input, Settings and held volume. Play a video in your streaming apps. To make DV Freedom your daily Home, choose it yourself in TV Home settings; the Streamer helper is a separate explicit choice.",16,MUTED));}
    void support(){page(0,"A report you can review.","This report omits TV addresses, peer/device IDs, keys, app inventory, backups and media. Nothing is uploaded automatically.");String report;try{JSONObject r=installer==null?null:installer.journal.last();report=new JSONObject().put("app","DV Freedom Phone Setup 0.1-alpha1").put("androidPhoneApi",Build.VERSION.SDK_INT).put("release",bundle==null?"unavailable":bundle.release.optString("versionName")).put("operation",r==null?"none":r.optString("state")).put("pairedTLSRequired",true).toString(2);}catch(Exception bad){report="Recovery record unreadable. No private record attached.";}page.addView(text(report,15,INK));String share=report;button("Choose where to share this report",true,()->startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,share),"Share reviewed report")));button("Back",false,()->{if(installer!=null)homeChoices();else welcome();});}
    void about(){page(0,"Private by default.","No analytics, cloud account, AI key or paid API calls. The only connection is to the private-network TV you choose. Encrypted per-TV ADB identities stay in this phone’s app storage; backup is disabled.");page.addView(text("This separate phone app is distributed under GPL-3.0-or-later because of its SPAKE2 dependency. The TV launcher retains its own MIT licence. LibADB: GPL-3.0-or-later OR Apache-2.0 (adapted); SPAKE2-Java: LGPL-3.0; Conscrypt: Apache-2.0; Bouncy Castle: MIT; Outfit: OFL. Corresponding sources and build instructions: github.com/DVOpenLabs/dv-freedom-launcher/tree/main/mobile.",15,INK));try{for(String file:getAssets().list("licences")){String selected=file;button("Licence · "+file,false,()->{page(0,selected,"Included third-party licence text");try{page.addView(text(new String(VerifiedBundle.read(getAssets().open("licences/"+selected),200000),java.nio.charset.StandardCharsets.UTF_8),14,INK));}catch(Exception bad){page.addView(text("Read the corresponding source licence in the project repository",16,INK));}button("Back to notices",true,this::about);});}}catch(Exception unavailable){page.addView(text("Full licence texts are also included in the corresponding source",16,INK));}button("Back",true,this::welcome);}
    @Override public void onBackPressed(){if(busy){Toast.makeText(this,"Wait for this operation to finish; reconnect and check if the app closes",Toast.LENGTH_LONG).show();return;}if(screen==0)super.onBackPressed();else if(screen==3)homeChoices();else if(screen==2){if(connection!=null)connection.close();welcome();}else welcome();}
    @Override protected void onStop(){if(!busy&&!gate&&connection!=null){connection.close();disconnected=true;}super.onStop();}
    @Override protected void onResume(){super.onResume();if(disconnected&&!busy&&!gate){disconnected=false;connect();}}
    @Override protected void onDestroy(){if(connection!=null)connection.close();worker.shutdownNow();deadlines.shutdownNow();ui.removeCallbacksAndMessages(null);super.onDestroy();}
}
